import React, { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { useAuth } from '../../context/AuthContext';
import toast from 'react-hot-toast';
import './Auth.css';

const Register = () => {
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    password: '',
    confirmPassword: ''
  });
  const [loading, setLoading] = useState(false);
  const { register } = useAuth();
  const navigate = useNavigate();

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (formData.password !== formData.confirmPassword) {
      toast.error('Passwords do not match');
      return;
    }

    setLoading(true);

    const result = await register(
      formData.name,
      formData.email,
      formData.password
    );

    if (result.success) {
      toast.success('Registration successful!');
      navigate('/user/dashboard');
    } else {
      toast.error(result.message);
    }
    setLoading(false);
  };

  return (
    <div className="login-wrapper">
      <div className="login-container">

        {/* LEFT SIDE: Dark Grey/Charcoal Branding */}
        <div className="login-branding">
          <div className="brand-content">
            <h1 className="brand-title">WELCOME</h1>
            <h3 className="brand-subtitle">START YOUR LEAD HUNT</h3>
            <p className="brand-desc">
              Join Lead Hunter today and unlock the power of global lead generation. 
              Find high-quality business leads from any country effortlessly.
            </p>
          </div>

          {/* 3D Bubbles Decoration */}
          <div className="bubble bubble-1"></div>
          <div className="bubble bubble-2"></div>
          <div className="bubble bubble-3"></div>
        </div>

        {/* RIGHT SIDE: Registration Form */}
        <div className="login-form-wrapper">
          <div className="login-card register-card">
            <h2 className="form-title">Create Account</h2>
            <p className="form-subtitle">Join Lead Hunter and start generating leads today.</p>

            <form onSubmit={handleSubmit}>
              <div className="input-group">
                <label>Full Name</label>
                <div className="input-with-icon">
                  <i className="fa-solid fa-user"></i>
                  <input 
                    type="text" 
                    name="name" 
                    value={formData.name} 
                    onChange={handleChange} 
                    required 
                    placeholder="Enter your full name" 
                  />
                </div>
              </div>

              <div className="input-group">
                <label>Email Address</label>
                <div className="input-with-icon">
                  <i className="fa-solid fa-envelope"></i>
                  <input 
                    type="email" 
                    name="email" 
                    value={formData.email} 
                    onChange={handleChange} 
                    required 
                    placeholder="Enter your email" 
                  />
                </div>
              </div>

              <div className="input-group">
                <label>Password</label>
                <div className="input-with-icon">
                  <i className="fa-solid fa-lock"></i>
                  <input 
                    type="password" 
                    name="password" 
                    value={formData.password} 
                    onChange={handleChange} 
                    required 
                    placeholder="Create a password" 
                  />
                  <span className="show-pass-icon">
                    <i className="fa-solid fa-eye-slash"></i>
                  </span>
                </div>
              </div>

              <div className="input-group">
                <label>Confirm Password</label>
                <div className="input-with-icon">
                  <i className="fa-solid fa-lock"></i>
                  <input 
                    type="password" 
                    name="confirmPassword" 
                    value={formData.confirmPassword} 
                    onChange={handleChange} 
                    required 
                    placeholder="Confirm your password" 
                  />
                </div>
              </div>

              <button type="submit" className="signin-btn" disabled={loading}>
                {loading ? 'Creating Account...' : 'Create Account'}
              </button>
            </form>

            <p className="auth-link">
              Already have an account? <Link to="/login">Sign In</Link>
            </p>
          </div>
        </div>

      </div>
    </div>
  );
};

export default Register;
